SET search_path TO lms, extensions;

CREATE TABLE lms.learner_progress (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  learner_id      UUID NOT NULL REFERENCES lms.users(id) ON DELETE CASCADE,
  module_id       UUID NOT NULL REFERENCES lms.modules(id) ON DELETE CASCADE,
  status          TEXT NOT NULL DEFAULT 'not_started'
                    CHECK (status IN ('not_started', 'in_progress', 'completed')),
  started_at      TIMESTAMPTZ,
  completed_at    TIMESTAMPTZ,
  marked_by       UUID REFERENCES lms.users(id),  -- teacher/admin who marked complete
  notes           TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (learner_id, module_id)
);
